export const IVUS_FIND={ivus:{ref:tr('正常參考段：血管壁可見「三層結構」——較亮的內膜、暗的中膜、亮的外膜；中膜外緣就是外彈性膜（EEM）。管腔內細細的斑點是血液的回音。'),
ca:tr('瀰漫鈣化：鈣化表面極亮，後方完全被遮住（聲影），看不到鈣化厚度，也看不到後方的血管外緣。鈣化弧越大、越接近整圈，支架越不容易撐開。'),
soft:tr('軟斑塊（纖維脂肪斑塊）：偏心、回音比外膜暗的低回音斑塊，後方沒有聲影；斑塊負荷高，但管腔還不算太窄。'),
tcfa:tr('易破裂斑塊：大片低回音斑塊、深處訊號逐漸衰減（attenuated plaque），血管往外撐大（正向重塑）。IVUS 解析度不足以量到薄纖維帽，要靠 OCT。'),
stent:tr('支架段：每根支架鋼絲是一個亮點、後方有陰影。中段被鈣化擋住，支架擴張不足（MSA ÷ 參考管腔面積 < 80%）；近端邊緣鋼絲和血管壁之間有血流空隙，是貼壁不良。'),
diss:tr('支架遠端邊緣剝離：一片內膜撕開翹進管腔（flap），後方是假腔的血流。要評估剝離的角度、長度、深度，決定是否需要再放一支支架。')},
oct:{ref:tr('正常參考段：OCT 可清楚分出內膜（亮）、中膜（暗帶）、外膜三層，組織訊號均勻；管腔因顯影劑沖洗而全黑。'),
ca:tr('瀰漫鈣化：OCT 中的鈣化是邊界銳利、訊號偏暗的區塊；光可以穿過鈣化，所以量得到厚度。鈣化弧＞180°、厚度＞0.5 mm、長度＞5 mm 時支架容易擴張不足，應先考慮旋磨或震波碎石。'),
soft:tr('軟斑塊（纖維脂肪斑塊）：訊號中等、較不均勻的偏心斑塊；深處訊號較快衰減，所以通常看不到外彈性膜。'),
tcfa:tr('易破裂斑塊（TCFA）：亮而薄的纖維帽（＜65 µm）覆蓋大片訊號暗、邊界模糊的脂質核心，帽下亮點是巨噬細胞堆積；脂質弧＞90°。這是日後斑塊破裂、急性心肌梗塞的高風險病灶。'),
stent:tr('支架段：每根鋼絲是一條亮線、後方全黑陰影，可以逐根判斷貼壁。中段被鈣化擋住擴張不足；近端邊緣鋼絲離開血管壁，貼壁不良距離＞0.4 mm 時較有臨床意義。'),
diss:tr('支架遠端邊緣剝離：OCT 清楚看到撕開翹起的內膜片（flap）和後方的假腔，可以量出剝離的弧度與深度。')}};
export const RTXT={sinus:{cap:tr('正常竇律：竇房結發出訊號，經心房、房室結短暫延遲後往下傳到心室。可在上方選擇常見的心律不整。')},
avnrt:{name:tr('AVNRT（慢–快型）'),cat:tr('心律不整 · 陣發性上心室頻脈'),title:tr('房室結迴旋性心搏過速（AVNRT，慢–快型）'),text:tr('房室結附近有兩條傳導路徑：慢徑路（藍）與快徑路（黃）。一個提早的心房早期收縮碰到快徑路還在不反應期，只能沿慢徑路往下傳，再從已恢復的快徑路往上折返，在房室結周圍形成一個小迴圈。每繞一圈同時往下啟動心室、往上啟動心房，所以 P 波藏在 QRS 裡或在 V1 形成假性 r′；心跳約每分鐘 140–200 下，QRS 窄。電燒目標：冠狀竇口與三尖瓣環之間的慢徑路。'),cap:tr('心電圖（II 導程示意）：規則窄 QRS 約 160/min，看不到 P 波（藏在 QRS 中，V1 可見假性 r′）。按「⚡ 電燒」看治療。'),abl:tr('電燒導管經股靜脈、下腔靜脈進入右心房，到冠狀竇口與三尖瓣環之間的慢徑路放電燒灼。')},
avrt:{name:tr('AVRT（順向型）'),cat:tr('心律不整 · 陣發性上心室頻脈'),title:tr('房室迴旋性心搏過速（AVRT，順向型）'),text:tr('心房與心室之間多了一條副傳導路徑（綠，此例在二尖瓣環左外側）。順向型 AVRT 的迴圈很大：電流經房室結、希氏束往下活化心室，再從副傳導路徑逆傳回左心房，繞回房室結。心室活化走正常路徑，所以 QRS 窄；逆行 P 波落在 QRS 之後的 ST 段（RP 間期 < PR 間期）。電燒目標：二尖瓣環上的副傳導路徑。'),cap:tr('心電圖（II 導程示意）：規則窄 QRS 約 180/min，QRS 後方 ST 段上可見倒立的逆行 P 波（RP < PR）。按「⚡ 電燒」看治療。'),abl:tr('大多數副傳導路徑位在二尖瓣環上，這裡採逆行主動脈途徑：電燒導管從股動脈經主動脈逆行而上，穿過主動脈瓣進入左心室，再彎到二尖瓣環下方的副傳導路徑放電燒灼。')},
flutter:{name:tr('典型心房撲動'),cat:tr('心律不整 · 心房撲動'),title:tr('典型心房撲動（三尖瓣峽部依賴型）'),text:tr('右心房內的大迴圈繞著三尖瓣環逆時針轉：沿心房中隔往上、沿右心房側壁往下，再通過下腔靜脈與三尖瓣之間的峽部（CTI，紅色標示）。心房每分鐘約 300 次，房室結通常 2:1 下傳，所以心室約每分鐘 150 下；II、III、aVF 導程可見鋸齒狀 F 波。電燒目標：在 CTI 燒一條線，阻斷迴圈。'),cap:tr('心電圖（II 導程示意）：鋸齒狀 F 波約 300/min，2:1 下傳，心室約 150/min。按「⚡ 電燒」看治療。'),abl:tr('三條導管都從股靜脈經下腔靜脈進入右心房：一條環狀 20 極導管（Halo）沿三尖瓣環繞右心房一圈，一條 10 極導管放進冠狀竇，兩者用來看電流繞行的方向；第三條才是電燒導管，從三尖瓣環往下腔靜脈逐點拖燒，在峽部（CTI）燒出一條連續的線。只要燒斷這條線，整個迴圈就無法繞行，不需要整圈都燒。')},
af:{name:tr('心房顫動'),cat:tr('心律不整 · 心房顫動'),title:tr('心房顫動'),text:tr('肺靜脈口的異常放電（閃光）觸發心房內多條小而亂竄的電流（子波），彼此碰撞、此起彼落，心房失去規律收縮。房室結只能不規則地讓部分電流通過，所以心跳「完全不規則」，心電圖沒有 P 波，只有細小的顫動波。電燒策略：肺靜脈隔離（PVI），在左右兩組肺靜脈口外圍各燒一圈，把觸發源隔開。'),cap:tr('心電圖（II 導程示意）：沒有 P 波，基線細小顫動波，QRS 間距完全不規則。按「⚡ 電燒」看治療。'),abl:tr('電燒導管與環狀定位導管（Lasso）一起從股靜脈經下腔靜脈進入右心房，穿過心房中隔到左心房；另一支冠狀竇導管從頸部經上腔靜脈放進冠狀竇當參考。Lasso 放在肺靜脈口記錄電位，電燒導管先沿左側兩條肺靜脈外圍逐點繞燒一大圈，再換到右側繞第二圈（肺靜脈隔離），把觸發源隔開。')},
vt:{name:'RVOT VT',cat:tr('心律不整 · 心室頻脈'),title:tr('右心室流出道心室頻脈（RVOT VT）'),text:tr('這不是迴旋，而是右心室流出道一個局部病灶（亮點）自己反覆快速放電，電流從流出道往下擴散到整個心室。因為不走正常傳導束，QRS 寬，呈左束支阻斷型、下軸（II、III、aVF 正向）。竇房結仍照自己的速度發出 P 波，與 QRS 無關（房室分離）。多見於結構正常的心臟。電燒目標：流出道的最早活化點。'),cap:tr('心電圖（II 導程示意）：寬 QRS 約 180/min，左束支阻斷型、下軸；P 波照竇律自己出現，和 QRS 無關。按「⚡ 電燒」看治療。'),abl:tr('電燒導管經下腔靜脈、右心房、三尖瓣進入右心室，到流出道的最早活化點放電燒灼。')}};
